from pptx import Presentation
p = Presentation('${DEMO}/company-decks/brand/company-design-template.pptx')
print("Slide width x height:", p.slide_width, p.slide_height)
print("--- Slide layouts ---")
for i, l in enumerate(p.slide_layouts):
    print(i, repr(l.name))
    for ph in l.placeholders:
        print("   ph idx=", ph.placeholder_format.idx, "type=", ph.placeholder_format.type, "name=", ph.name)
print("--- Existing slides ---")
for i, s in enumerate(p.slides):
    print(i, "layout=", s.slide_layout.name)
    for ph in s.placeholders:
        try:
            txt = ph.text_frame.text
        except:
            txt = "(no tf)"
        print("   ph idx=", ph.placeholder_format.idx, "name=", ph.name, "text=", repr(txt))
